1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * The single source of truth for an owner's canonical region, derived from the postcode and city. A
7	 * region is a short code (NSW, VIC, QLD) fixed by two lookup tables: the inclusive 4-digit postcode
8	 * range per region, and the city-to-region fallback used when the postcode yields nothing.
9	 *
10	 * <p>{@link #fromPostcode} answers the region for a postcode alone (or {@code null});
11	 * {@link #identifierRegionCode} is the one derivation the identifiers embed — the REGION prefix of an
12	 * owner's {@code memberId} — folding an absent region to {@code UNKNOWN}; {@link #regionOf} reads that
13	 * prefix back out of a {@code memberId}, which is how a whole owner resolves to a locality.
14	 */
15	public final class OwnerRegion {
16	
17	    /** City -> canonical region, from the fixed city-to-region table. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
20	
21	    /** Region -> inclusive 4-digit postcode range {low, high}. */
22	    private static final Map<String, int[]> REGION_RANGE = Map.of(
23	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
24	
25	    /** Region -> IANA timezone name, from the fixed region-to-timezone table. */
26	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
27	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
28	
29	    private OwnerRegion() {
30	    }
31	
32	    /** The canonical region for {@code city} from the fixed city-to-region table, or {@code null}. */
33	    static String regionForCity(String city) {
34	        return city == null ? null : CITY_REGION.get(city);
35	    }
36	
37	    /** The known region codes (NSW, VIC, QLD) — the prefixes a memberId's REGION segment can take. */
38	    static Iterable<String> knownRegions() {
39	        return REGION_TIMEZONE.keySet();
40	    }
41	
42	    /** The inclusive 4-digit postcode range {low, high} for {@code region}, or {@code null}. */
43	    static int[] rangeForRegion(String region) {
44	        return REGION_RANGE.get(region);
45	    }
46	
47	    /**
48	     * The region whose fixed range contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
49	     * QLD 4000-4099), or {@code null} when the postcode is absent, non-numeric, or in no known range.
50	     */
51	    public static String fromPostcode(String postcode) {
52	        if (postcode == null || postcode.isBlank()) {
53	            return null;
54	        }
55	        int value;
56	        try {
57	            value = Integer.parseInt(postcode.trim());
58	        }
59	        catch (NumberFormatException ex) {
60	            return null;
61	        }
62	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
63	            int[] range = entry.getValue();
64	            if (value >= range[0] && value <= range[1]) {
65	                return entry.getKey();
66	            }
67	        }
68	        return null;
69	    }
70	
71	    /**
72	     * The region code the identifiers embed — the REGION segment of an owner's {@code memberId},
73	     * derived from the postcode: the plain region ({@link #fromPostcode}) when the postcode maps to a
74	     * known region, else {@code UNKNOWN}. This is the single source for the region that goes <em>into</em>
75	     * an identifier, kept distinct from the user-facing locality that {@link #regionOf} reads back
76	     * <em>out</em> of an assigned id.
77	     */
78	    public static String identifierRegionCode(String postcode) {
79	        String region = fromPostcode(postcode);
80	        return region == null ? "UNKNOWN" : region;
81	    }
82	
83	    /**
84	     * The REGION prefix of a {@code memberId} ({@code <REGION><FY><HASH8><CHK>}) — the owner's locality.
85	     * Now that identity is region-and-hash, the locality is read straight off the assigned memberId
86	     * rather than recomputed, so it always matches the id. {@code UNKNOWN} when the id is absent or has
87	     * no known region prefix.
88	     */
89	    public static String regionOf(String memberId) {
90	        return MemberId.regionOf(memberId);
91	    }
92	
93	    /**
94	     * The IANA timezone name for the owner's region, resolved from the REGION prefix of the
95	     * {@code memberId} through the fixed region-to-timezone table (NSW -> Australia/Sydney,
96	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). {@code null} when the region is
97	     * absent or unknown.
98	     */
99	    public static String timezoneOf(String memberId) {
100	        return REGION_TIMEZONE.get(regionOf(memberId));
101	    }
102	}
103

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The single source of truth for an owner's unified {@code memberId}, formatted
5	 * {@code <REGION><FY><HASH8><CHK>}: REGION is the region code derived from the postcode
6	 * (NSW/VIC/QLD, else {@code UNKNOWN}), FY the two-digit fiscal year, HASH8 the first 8 upper-case
7	 * hex characters of SHA-256 over {@code normalizedTelephone + lastName} (the same HASH8 the
8	 * region-and-hash identity uses — see {@link OwnerIdentity#customerHash}), and CHK a single Luhn
9	 * check digit over the decimal digits of {@code <REGION><FY><HASH8>}.
10	 *
11	 * <p>{@link #of} assembles the id from its parts when an owner is created; {@link #regionOf} and
12	 * {@link #fiscalYearCodeOf} read the REGION and FY segments back out of an assigned id, which is how
13	 * the owner's locality, timezone and fiscal year all resolve straight off the memberId. A collision
14	 * with an existing owner's memberId is de-duplicated by appending {@code -<n>} (see
15	 * {@link AssignMemberId}); the suffix is not part of the segments the readers below extract.
16	 */
17	public final class MemberId {
18	
19	    /** The fixed-width tail after the REGION prefix: FY (2) + HASH8 (8) + CHK (1). */
20	    private static final int TAIL_LENGTH = 11;
21	
22	    private MemberId() {
23	    }
24	
25	    /**
26	     * The base memberId {@code <REGION><FY><HASH8><CHK>} assembled from its parts (before any
27	     * collision suffix): CHK is the Luhn check digit over the decimal digits of
28	     * {@code region + fiscalYearCode + hash8}.
29	     */
30	    public static String of(String region, String fiscalYearCode, String hash8) {
31	        String core = region + fiscalYearCode + hash8;
32	        return core + OwnerIdentity.luhnCheckDigit(core);
33	    }
34	
35	    /**
36	     * The REGION prefix of {@code memberId} — one of the known regions (NSW, VIC, QLD), else
37	     * {@code UNKNOWN} (which also covers an absent or malformed id).
38	     */
39	    public static String regionOf(String memberId) {
40	        if (memberId != null) {
41	            for (String region : OwnerRegion.knownRegions()) {
42	                if (memberId.startsWith(region)) {
43	                    return region;
44	                }
45	            }
46	        }
47	        return "UNKNOWN";
48	    }
49	
50	    /**
51	     * The two-digit FY segment of {@code memberId}: the two characters immediately after the REGION
52	     * prefix. Null when the id is absent or too short to carry the FY segment (before the HASH8/CHK
53	     * tail).
54	     */
55	    public static String fiscalYearCodeOf(String memberId) {
56	        if (memberId == null) {
57	            return null;
58	        }
59	        int start = regionOf(memberId).length();
60	        if (memberId.length() < start + TAIL_LENGTH) {
61	            return null;
62	        }
63	        return memberId.substring(start, start + 2);
64	    }
65	}
