6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's unified {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} — the
12	 * region code derived from the postcode (NSW/VIC/QLD, else {@code UNKNOWN}), the two-digit fiscal year
13	 * the registrationDate falls in, the first 8 upper-case hex characters of SHA-256 over
14	 * {@code normalizedTelephone + lastName}, and a single Luhn check digit over the digits of
15	 * {@code <REGION><FY><HASH8>} (see {@link MemberId}, e.g. {@code NSW271A2B3C4D5}). The base id is fully
16	 * determined by the owner's region, fiscal year and hashed identity.
17	 *
18	 * <p>When that base id collides with an existing owner's {@code memberId}, it is de-duplicated by
19	 * appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique (e.g.
20	 * {@code NSW271A2B3C4D5-2}). Runs before {@link SaveOwner}, so {@link OwnerRepository#findAll()}
21	 * returns only the owners that predate this create.
22	 */
23	public class AssignMemberId {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        owner.setMemberId(uniqueId(baseId(owner), assignedIds(ownerRepository)));
27	    }
28	
29	    /**
30	     * The owner's base memberId before any collision suffix, formatted {@code <REGION><FY><HASH8><CHK>}.
31	     * Fully determined by the owner, so equal owners produce the same base.
32	     */
33	    private static String baseId(Owner owner) {
34	        String region = OwnerRegion.identifierRegionCode(owner.getPostcode());
35	        String fiscalYearCode = OwnerMembership.fiscalYearCode(owner.getRegistrationDate());
36	        String hash8 = OwnerIdentity.customerHash(owner.getTelephone(), owner.getLastName());
37	        return MemberId.of(region, fiscalYearCode, hash8);
38	    }
39	
40	    /**
41	     * {@code base} de-duplicated against {@code existing} by appending {@code -<n>} with the smallest
42	     * {@code n} of 2 or more that makes it unique (e.g. {@code NSW271A2B3C4D5-2}); {@code base} itself
43	     * when already free.
44	     */
45	    private static String uniqueId(String base, Set<String> existing) {
46	        String id = base;
47	        for (int n = 2; existing.contains(id); n++) {
48	            id = base + "-" + n;
49	        }
50	        return id;
51	    }
52	
53	    /** The ids already assigned to existing owners — the set a new memberId must avoid colliding with. */
54	    private static Set<String> assignedIds(OwnerRepository ownerRepository) {
55	        Set<String> existing = new HashSet<>();
56	        for (Owner other : ownerRepository.findAll()) {
57	            if (other.getMemberId() != null) {
58	                existing.add(other.getMemberId());
59	            }
60	        }
61	        return existing;
62	    }
63	}
