1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single source of truth for an owner's membership scoring: the {@code membershipPoints} an owner
9	 * has earned and the {@code membershipLevel} those points band into, plus the fiscal-year primitive
10	 * both the scoring's tenure rule and the owner's fiscal/membership-number formatting share.
11	 *
12	 * <p>These are pure functions of an owner's already-stored fields; {@link OwnerMapper} delegates its
13	 * {@code membershipPoints} and {@code membershipLevel} derivations here, mirroring how it delegates to
14	 * {@link OwnerIdentity} and {@link OwnerRegion}. The fiscal-year primitive also feeds the FY segment of
15	 * an owner's {@code memberId} (see {@link MemberId} and {@link AssignMemberId}).
16	 */
17	public final class OwnerMembership {
18	
19	    private OwnerMembership() {
20	    }
21	
22	    /**
23	     * The fiscal year the {@code date} falls in, as an integer. The fiscal year starts on 1 July and is
24	     * named by the calendar year in which it ends, so 1 July 2026 - 30 June 2027 is fiscal year 2027: a
25	     * date in July or later belongs to the next calendar year's fiscal year, an earlier date to the
26	     * current calendar year's.
27	     */
28	    public static int fiscalYearOf(LocalDate date) {
29	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
30	    }
31	
32	    /**
33	     * The two-digit fiscal-year code for {@code date}: the {@link #fiscalYearOf(LocalDate) fiscal year}
34	     * it falls in taken mod 100 and zero-padded to two digits (e.g. {@code 27}). This is the FY segment
35	     * of an owner's {@code memberId} ({@code <REGION>27<HASH8><CHK>}), from which the mapper's
36	     * {@code fiscalYear} ({@code FY27}) is read back.
37	     */
38	    public static String fiscalYearCode(LocalDate date) {
39	        return String.format("%02d", fiscalYearOf(date) % 100);
40	    }
41	
42	    /**
43	     * The owner's membership points. Starts at 0; add 2 when an email is present; add 1 when the owner's
44	     * name was unique on creation (namesakeCount is 0); add 2 for a household of 3 or more members; add 3
45	     * for tenure of one or more elapsed fiscal years (the current fiscal year differs from the fiscal
46	     * year the registrationDate falls in; fiscal year starting 1 July).
47	     */
48	    public static int points(Owner owner) {
49	        int points = 0;
50	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
51	        if (hasEmail) {
52	            points += 2;
53	        }
54	        Integer namesakeCount = owner.getNamesakeCount();
55	        if (namesakeCount != null && namesakeCount == 0) {
56	            points += 1;
57	        }
58	        Integer householdSize = owner.getHouseholdSize();
59	        if (householdSize != null && householdSize >= 3) {
60	            points += 2;
61	        }
62	        if (owner.getRegistrationDate() != null
63	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(owner.getRegistrationDate()) >= 1) {
64	            points += 3;
65	        }
66	        return points;
67	    }
68	
69	    /**
70	     * The owner's membership level, derived by banding {@link #points(Owner)}: level 1 for 0-1 points,
71	     * level 2 for 2-3, level 3 for 4-5, level 4 for 6 or more.
72	     *
73	     * <p>When a {@code membershipLevelCap} is recorded (set at creation from the owner's household — see
74	     * {@link CapMembershipLevel}), the banded level is capped to it: a new owner's level cannot exceed
75	     * one above the current maximum level among their household members. A null cap (no existing
76	     * household member) leaves the banded level unchanged.
77	     */
78	    public static int level(Owner owner) {
79	        int level;
80	        int points = points(owner);
81	        if (points >= 6) {
82	            level = 4;
83	        }
84	        else if (points >= 4) {
85	            level = 3;
86	        }
87	        else if (points >= 2) {
88	            level = 2;
89	        }
90	        else {
91	            level = 1;
92	        }
93	        Integer cap = owner.getMembershipLevelCap();
94	        if (cap != null && level > cap) {
95	            level = cap;
96	        }
97	        return level;
98	    }
99	}
