24	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
25	
26	    private static final JsonMapper JSON = JsonMapper.builder().build();
27	
28	    /** Monotonically increasing sequence stamped onto each event, shared across all creates. */
29	    private static final AtomicLong SEQUENCE = new AtomicLong();
30	
31	    public void service(@Val Owner owner) {
32	        int membershipLevel = OwnerMembership.level(owner);
33	
34	        AUDIT.info(
35	                "Created owner id={} memberId={} registrationDate={} membershipLevel={}",
36	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
37	
38	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
39	                primaryIdentifier(owner), membershipLevel);
40	        AUDIT.info(JSON.writeValueAsString(event));
41	    }
42	
43	    /**
44	     * The owner's primary identifier carried by the {@link OwnerCreatedEvent} — the unified
45	     * {@code memberId}. This single method is the one place the event's identity source is defined.
46	     */
47	    private static String primaryIdentifier(Owner owner) {
48	        return owner.getMemberId();
49	    }
50	}
