package org.springframework.samples.petclinic.acceptance;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.LocalDate;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/**
 * identity-v2 behaviour contract: the identifiers (memberId, identityKey, householdId) are re-derived
 * under version 2 by mixing in a fixed 'V2' tag, while the user-facing locality, timezone and owner
 * segment stay the plain region (no 'V2'). The audit event moves to schema version 2.
 */
class IdentityV2Test extends AcceptanceBase {

	/** The identifiers carry the V2 tag; the user-facing locality/timezone/segment do not. */
	@Test
	void identifiersCarryV2ButUserFacingFieldsStayPlain() throws Exception {
		int id = createOwnerOk(knownOwner("Sydney"));
		JsonNode o = fetchOwner(id);

		// The member id embeds the version-tagged region ("NSWV2..."), never the plain region alone.
		String memberId = o.path("identity").path("memberId").asText();
		assertThat(memberId).startsWith("NSWV2");

		// Locality/timezone/segment are read back as the PLAIN region — no 'V2' leaks in.
		assertThat(o.get("locality").asText()).isEqualTo("NSW");
		assertThat(o.get("timezone").asText()).isEqualTo("Australia/Sydney");
		assertThat(o.get("ownerSegment").asText()).doesNotContain("V2");
		assertThat(o.get("ownerSegment").asText()).endsWith("_METRO");

		// The FY segment still parses correctly past the version tag.
		LocalDate today = LocalDate.now();
		int fy = today.getMonthValue() >= 7 ? today.getYear() + 1 : today.getYear();
		assertThat(o.get("fiscalYear").asText()).isEqualTo(String.format("FY%02d", fy % 100));
	}

	/** householdId is the version-2 derivation (12 hex over 'V2|lastName|postcode') and differs from V1. */
	@Test
	void householdIdIsVersion2Derivation() throws Exception {
		ObjectNode payload = knownOwner("Sydney");
		String lastName = payload.get("lastName").asText();
		String postcode = payload.get("postcode").asText();
		int id = createOwnerOk(payload);

		String householdId = fetchOwner(id).path("identity").path("householdId").asText();

		String norm = lastName.trim().replaceAll("\\s+", " ").toLowerCase();
		String v2 = shaHex("V2|" + norm + "|" + postcode, 12);
		String v1 = shaHex(norm + "|" + postcode, 12);
		assertThat(householdId).isEqualTo(v2).isNotEqualTo(v1);
	}

	/** identityKey is grouped under identity and is a 64-char lower-case hex digest. */
	@Test
	void identityKeyIsGroupedAndHex() throws Exception {
		int id = createOwnerOk(knownOwner("Sydney"));
		JsonNode o = fetchOwner(id);

		assertThat(o.path("identity").path("identityKey").asText()).matches("[0-9a-f]{64}");
		// The three identifiers no longer sit at the top level.
		assertThat(o.has("memberId")).isFalse();
		assertThat(o.has("householdId")).isFalse();
		assertThat(o.has("identityKey")).isFalse();
	}

	/** The structured audit event is emitted at schema version 2. */
	@Test
	void auditEventIsSchemaVersion2() throws Exception {
		try (AuditLogCapture audit = new AuditLogCapture()) {
			createOwnerOk(knownOwner("Sydney"));
			assertThat(audit.anyContains("\"schemaVersion\":2", "\"event\":\"OWNER_CREATED\"")).isTrue();
		}
	}
}

